import { Component } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';

@Component({
  selector: 'app-root',
  imports: [ReactiveFormsModule],
  template: `
    <h1>Nueva tarea</h1>
    <form [formGroup]="form" (ngSubmit)="guardar()">
      <label>Título <input formControlName="titulo" /></label>
      @let titulo = form.controls.titulo;
      @if (titulo.touched && titulo.hasError('required')) {
        <small>El título es obligatorio.</small>
      } @else if (titulo.touched && titulo.hasError('minlength')) {
        <small>Escribí al menos 3 letras.</small>
      }
      <button type="submit">Crear tarea</button>
    </form>
    <p>Enviado: {{ enviado }}</p>
  `,
})
export class App {
  enviado = '';

  readonly form = new FormGroup({
    titulo: new FormControl('', {
      nonNullable: true,
      validators: [Validators.required, Validators.minLength(3)],
    }),
  });

  guardar() {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    this.enviado = this.form.getRawValue().titulo;
    this.form.reset();
  }
}
